language st
PROGRAM TankLevelControl
VAR
    LowFloat AT %IX0.0 : BOOL;
    HighFloat AT %IX0.1 : BOOL;
    ValveOpen AT %QX0.0 : BOOL;
    ValveTimer AT %QX0.1 : BOOL;
    ValveCounter AT %QX0.2 : INT;
    LastOpenTime : TON;
END_VAR

(* Initialize the timer to 0 seconds *)
LastOpenTime(IN := 0, PT := T#0s);

(* Initialize the counter to 0 *)
ValveCounter := 0;

(* Initialize the valve timer to 0 seconds *)
ValveTimer(IN := 0, PT := T#0s);

(* Initialize the valve to closed *)
ValveOpen := FALSE;

(* Main Control Loop *)
CASE LowFloat OF
    TRUE:
        (* Open the valve immediately when low float is detected *)
        ValveOpen := TRUE;
        ValveCounter := 0;
        ValveTimer(IN := 0, PT := T#0s);
END_CASE;

CASE HighFloat OF
    TRUE:
        (* Close the valve immediately when high float is detected *)
        ValveOpen := FALSE;
        ValveCounter := 0;
        ValveTimer(IN := 0, PT := T#0s);
END_CASE;

END_PROGRAM
END

